import './style.css';
import { categories } from './data.js';
import { cards, evidenceSources } from './content.js';
import { buildPlan, calculateGrade, reviewDate } from './planner.js';
import { examples } from './examples.js';
import researchSummary from './research-summary.json';

const $ = s => document.querySelector(s);
const h = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = {
 arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>', book:'<path d="M3 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-3H3V4Zm18 0h-6a3 3 0 0 0-3 3v14a4 4 0 0 1 4-3h5V4Z"/>',
 spark:'<path d="m12 3 2.2 6.8L21 12l-6.8 2.2L12 21l-2.2-6.8L3 12l6.8-2.2L12 3Z"/>', target:'<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="3"/><path d="m16 8 5-5"/>',
 heart:'<path d="M20.8 4.6a5.3 5.3 0 0 0-7.5 0L12 5.9l-1.3-1.3a5.3 5.3 0 0 0-7.5 7.5L12 21l8.8-8.9a5.3 5.3 0 0 0 0-7.5Z"/>', home:'<path d="m3 10 9-7 9 7v11H3V10Zm6 11v-8h6v8"/>',
 leaf:'<path d="M20 3C8 2 2 8 5 15s14 4 15-12Z"/><path d="m4 21 10-12"/>', people:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m2-17a3 3 0 0 1 0 6m4 11v-3a6 6 0 0 0-3-5"/>',
 moon:'<path d="M20.5 13A8.7 8.7 0 0 1 11 3.5 9 9 0 1 0 20.5 13Z"/>', access:'<circle cx="12" cy="4" r="2"/><path d="m4 9 8 2 8-2m-8 2v5m0 0-5 6m5-6 5 6"/>', clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',
 sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v2m0 18v2M1 12h2m18 0h2M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>', compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-2 6-6 2 2-6 6-2Z"/>',
 search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>', check:'<path d="m5 12 4 4L20 5"/>', plus:'<path d="M12 5v14M5 12h14"/>', close:'<path d="m6 6 12 12M6 18 18 6"/>',
 external:'<path d="M14 3h7v7m0-7-10 10M10 3H3v18h18v-7"/>', filter:'<path d="M3 6h18M6 12h12M9 18h6"/>', download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>', shield:'<path d="m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6l9-4Z"/><path d="m8 12 3 3 5-6"/>',
 reset:'<path d="M4 10a8 8 0 1 1 1 8M4 4v6h6"/>', mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>', layers:'<path d="m12 3 10 6-10 6L2 9l10-6Zm-10 12 10 6 10-6M2 12l10 6 10-6"/>'
};
const icon = (name, cls='') => `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name] || paths.spark}</svg>`;
const catIcon = {school:'book',start:'spark',focus:'target',feelings:'heart',home:'home',missing:'leaf',friends:'people',health:'moon',access:'access',time:'clock',needs:'sun',future:'compass'};
const btn = (label, action, cls='btn', extra='') => `<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const link = (label,url,cls='text-link') => `<a class="${cls}" href="${h(url)}" target="_blank" rel="noopener noreferrer">${label}${icon('external')}</a>`;
const key = 'next-step-study-v1';
const blankStudy = () => ({question:'',answer:'',correction:'',reveal:false,cards:[],flipped:[],errorQuestion:'',errorType:'Understanding',errorReason:'',errors:[],example:'linear',exampleAnswer:'',exampleFeedback:'',hint:false,tasks:[],taskTitle:'',taskDate:'',taskMinutes:20,grades:[{name:'Major',score:80,weight:70},{name:'Minor',score:90,weight:20},{name:'Other',score:100,weight:10}]});
let saved=null;
try { const p=JSON.parse(localStorage.getItem(key)); if(p?.version===1 && p.work && Array.isArray(p.work.cards) && Array.isArray(p.work.tasks)) saved=p.work; } catch {}
const state={page:'home',selected:[],details:[],search:'',showAll:false,primary:'',explanation:'',minutes:15,energy:'Some',priority:'Make a plan',topic:'',small:false,approach:'',plan:false,done:[],feedback:'',modal:null,sourceIds:[],safe:'',draftKind:'Private conversation',draft:'',timer:0,running:false,method:'Recall',study:{...blankStudy(),...(saved||{}),reveal:false,flipped:[]},saveWork:!!saved,researchQuery:'',researchTopic:'All topics',researchType:'All types',researchSort:'Catalog order',researchYear:'Any year',researchPage:1,researchTab:'papers',large:false};
let catalog=null, catalogError='',catalogPromise=null,lastFocus=null;
const app=$('#app');
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
function toast(message){$('#notice').textContent=message;setTimeout(()=>{const n=$('#notice');if(n?.textContent===message)n.textContent='';},6500);}
function persist(){if(!state.saveWork)return;try{localStorage.setItem(key,JSON.stringify({version:1,work:{...state.study,flipped:[],reveal:false}}));}catch{state.saveWork=false;toast('Saving is unavailable in this browser. Your current work is still here.');}}
function navigate(page){state.page=page;state.modal=null;render();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});if(page==='research')loadCatalog();}
function loadCatalog(){if(catalog||catalogPromise)return;catalogPromise=import('./research-catalog.json').then(m=>{catalog=m.default;if(state.page==='research')render();}).catch(()=>{catalogError='The research index could not load. Try again when you have a connection.';catalogPromise=null;if(state.page==='research')render();});}
function render(){
 document.documentElement.classList.toggle('large-text',state.large);
 app.innerHTML=`<a class="skip-link" href="#main">Skip to content</a><header class="site-header"><div class="header-inner"><a href="#" class="brand" data-action="home" aria-label="Next Step home"><span class="brand-mark">n${icon('arrow')}</span>next step<span class="brand-period">.</span></a><nav aria-label="Main navigation">${[['home','For you'],['study','Study studio'],['research','Research library'],['plan','My plan']].map(([p,l])=>btn(l,'nav','nav-link '+((state.page===p||(p==='home'&&['details','context'].includes(state.page)))?'active':''),`data-page="${p}" ${state.page===p?'aria-current="page"':''}`)).join('')}</nav><div class="header-tools">${btn(icon('people')+'<span>Find support</span>','support','support-btn')}${btn('Aa','text','text-size','aria-label="Toggle larger text" aria-pressed="'+state.large+'"')}</div></div></header>
 <main id="main" tabindex="-1">${state.page==='home'?homeView():state.page==='details'?detailsView():state.page==='context'?contextView():state.page==='plan'?planView():state.page==='study'?studyView():researchView()}</main>
 <footer><a href="#" class="footer-brand" data-action="home">next step.</a><span>A little support. A way forward.</span><div>${btn('How the research works','methods','footer-link')}${btn('Privacy & your choices','privacy','footer-link')}</div><p>Student-built support tool · Not monitored · Sensitive support content awaits qualified review.</p></footer><div id="notice" class="toast" role="status" aria-live="polite"></div>${state.modal?modalView():''}`;
}
function homeView(){
 const visible=categories.filter(c=>(c.title+' '+c.subs.join(' ')).toLowerCase().includes(state.search.toLowerCase()));
 const show=state.search||state.showAll?visible:visible.slice(0,4);
 return `<section class="hero wrap"><div class="hero-copy"><span class="eyebrow"><span class="status-dot"></span> BIG DAYS. SMALL STARTS.</span><h1>A lot on your mind.<br>One <em>next step.</em></h1><p>School, life, or a bit of both. Find practical help that meets you where you are—and a first step you can actually take.</p><div class="hero-actions">${btn('Find my next step '+icon('arrow'),'jump-categories','btn primary')}${btn('Just help me study','quick-study','btn secondary')}</div><div class="trust-line"><span>${icon('check')}No account</span><span>${icon('check')}Your pace</span><span>${icon('check')}No streaks</span></div></div>
 <div class="hero-art" aria-label="Example of a small study plan"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><span class="art-spark">✳</span><div class="sample-label">A LITTLE LESS OVERWHELM</div><div class="sample-plan"><div class="sample-head"><span class="sample-icon">${icon('leaf')}</span><span>YOUR NEXT 10 MINUTES<small>An example, not another to-do list.</small></span><span class="sample-dot">···</span></div><h2>You don’t have to do it all.</h2><div class="sample-task"><span class="step-circle">1</span><div><strong>Make the first move.</strong><small>Open one question. That counts.</small></div><span class="time-tag">2 min</span></div><div class="sample-task"><span class="step-circle lavender">2</span><div><strong>Try. Check. Learn.</strong><small>One idea, from memory.</small></div><span class="time-tag">5 min</span></div><div class="sample-task"><span class="step-circle peach">3</span><div><strong>Leave a way back.</strong><small>Write your next small step.</small></div><span class="time-tag">3 min</span></div><div class="sample-bottom">Small enough to start. Flexible enough for you.${icon('spark')}</div></div><div class="floating-note">${icon('heart')}You’re a person.<br><strong>Not a productivity score.</strong></div></div></section>
 <section class="proof-strip wrap" aria-label="What is available"><span>${icon('compass')}<strong>12</strong> ways to find support</span><span>${icon('layers')}<strong>${Object.keys(cards).length}</strong> specific situations</span><span>${icon('book')}<strong>${Number(researchSummary.count).toLocaleString()}</strong> papers indexed</span>${btn('Explore the research '+icon('arrow'),'open-research','text-link')}</section>
 <section class="wrap chooser" id="choose"><div class="section-heading"><div><span class="eyebrow">01 / START WHERE YOU ARE</span><h2>What’s getting in the way?</h2><p>Choose one or more. You can skip the details.</p></div><label class="search-field">${icon('search')}<input id="category-search" aria-label="Search situations" placeholder="Try “phone”, “parents”, “sleep”…" value="${h(state.search)}" data-field="search"></label></div><div class="category-grid">${show.map(c=>`<button type="button" class="category ${state.selected.includes(c.id)?'selected':''}" data-action="category" data-value="${c.id}" aria-pressed="${state.selected.includes(c.id)}"><span class="category-icon tone-${categories.indexOf(c)%6}">${icon(catIcon[c.id])}</span><span class="category-check">${icon(state.selected.includes(c.id)?'check':'plus')}</span><h3>${h(c.title)}</h3><p>${h(c.description)}</p></button>`).join('')||'<div class="empty-state">No exact match. Try another word, or choose “Something else.”</div>'}</div>
 <div class="chooser-extras">${!state.search?btn(state.showAll?'Show fewer categories':'See all 12 categories '+icon('plus'),'show-all','text-link'):''}<div>${['I’m not sure','Something else'].map(s=>btn(h(s),'other','chip '+(state.selected.includes(s)?'selected':''),`data-value="${h(s)}" aria-pressed="${state.selected.includes(s)}"`)).join('')}</div></div><div class="continue-bar"><span>${state.selected.length?`<strong>${state.selected.length} selected.</strong> We’ll take it one step at a time.`:'You don’t need the perfect words to begin.'}</span>${btn('Find my next step '+icon('arrow'),'continue','btn primary',state.selected.length?'':'disabled')}</div></section>
 <section class="wrap ways-section"><div><span class="eyebrow">A TOOLBOX, NOT A TEST</span><h2>Help you can <em>put to work.</em></h2></div><div class="ways-grid"><article class="way-card sage">${icon('target')}<h3>Get unstuck.</h3><p>A plan for what’s actually in your way, with a smaller fallback when you need it.</p>${btn('Find a first step '+icon('arrow'),'jump-categories','text-link')}</article><article class="way-card lilac">${icon('book')}<h3>Study with a strategy.</h3><p>Recall cards, worked examples, mistake reviews, and a plan for your deadlines.</p>${btn('Open the study studio '+icon('arrow'),'open-study','text-link')}</article><article class="way-card apricot">${icon('people')}<h3>Bring a person in.</h3><p>Find the right kind of support and the words to ask for it. You choose what to share.</p>${btn('Find human support '+icon('arrow'),'support','text-link')}</article></div></section>
 <section class="wrap evidence-banner"><div class="evidence-symbol">${icon('layers')}</div><div><span class="eyebrow">CURIOUS ABOUT THE WHY?</span><h2>Real sources. Clear limits.</h2><p>Explore ${Number(researchSummary.count).toLocaleString()} indexed papers and ${evidenceSources.length} checked source summaries. See what supports an idea, and what hasn’t been tested.</p></div>${btn('Open research library '+icon('arrow'),'open-research','btn secondary')}</section>`;
}
function progress(step){return `<div class="flow-progress" aria-label="Step ${step} of 3">${['Choose a starting point','Make it specific','Make it yours'].map((l,n)=>`<span class="${n+1===step?'current':n+1<step?'complete':''}"><b>${n+1<step?icon('check'):n+1}</b>${l}</span>`).join('')}</div>`;}
function detailsView(){return `<section class="wrap flow">${progress(2)}<span class="eyebrow">A LITTLE MORE CONTEXT</span><h1>What feels <em>familiar?</em></h1><p class="flow-intro">Pick what fits. These choices change the help you get.</p>${categories.filter(c=>state.selected.includes(c.id)).map(c=>`<fieldset class="detail-group"><legend><span class="category-icon tone-${categories.indexOf(c)%6}">${icon(catIcon[c.id])}</span>${h(c.title)}</legend><div class="detail-grid">${c.subs.map(s=>btn(h(s)+(state.details.includes(s)?icon('check'):icon('plus')),'detail','detail-chip '+(state.details.includes(s)?'selected':''),`data-value="${h(s)}" aria-pressed="${state.details.includes(s)}"`)).join('')}</div></fieldset>`).join('')}${state.selected.some(s=>['Something else','I’m not sure'].includes(s))?`<article class="panel"><h2>You can start without a label.</h2><p>Choose study help or help finding a person on the next screen. A few optional words will appear in your plan as your own note; this app does not interpret or diagnose them.</p><label class="field">Your note (optional)<textarea id="explanation" data-field="explanation" maxlength="300" placeholder="Keep personal identifying details out of your note.">${h(state.explanation)}</textarea></label></article>`:''}<div class="flow-actions">${btn('Back','back-home','btn secondary')}${btn(state.details.length?'Make it mine '+icon('arrow'):'Skip details '+icon('arrow'),'to-context','btn primary')}</div></section>`;}
function contextView(){const safety=state.details.some(s=>/unsafe|Bullying|Unhealthy relationship/.test(s));return `<section class="wrap flow context-flow">${progress(3)}<div class="context-layout"><div><span class="eyebrow">A PLAN THAT FITS TODAY</span><h1>Your day.<br><em>Your pace.</em></h1><p class="flow-intro">A few practical choices. No need to share your whole story.</p><div class="context-aside">${icon('leaf')}<p>Low energy is useful information. We’ll make the first step smaller.</p></div></div><div class="panel context-form">${state.details.length>1?`<label class="field">Which would you like to start with?<select id="primary" data-field="primary">${state.details.map(s=>`<option ${state.primary===s?'selected':''}>${h(s)}</option>`).join('')}</select></label>`:''}${safety?`<fieldset><legend>Are you safe where you are right now?</legend><div class="chips">${['Yes','No','Not sure','Prefer not to answer'].map(s=>btn(s,'safe','chip '+(state.safe===s?'selected':''),`data-value="${s}" aria-pressed="${state.safe===s}"`)).join('')}</div></fieldset>`:''}<label class="field">What would help most first?<select id="priority" data-field="priority">${['Make a plan','Start schoolwork','Feel supported','Find a person to help'].map(s=>`<option ${state.priority===s?'selected':''}>${s}</option>`).join('')}</select></label><fieldset><legend>How much time feels manageable?</legend><div class="chips">${[5,15,30,60].map(n=>btn(n+' min','minutes','chip '+(state.minutes===n?'selected':''),`data-value="${n}" aria-pressed="${state.minutes===n}"`)).join('')}</div><label class="custom-time">Or choose minutes <input id="minutes" data-field="minutes" type="number" min="1" max="60" value="${state.minutes}" aria-label="Available minutes"></label></fieldset><fieldset><legend>What’s your energy like?</legend><div class="chips">${['Very low','Some','Enough'].map(s=>btn(s,'energy','chip '+(state.energy===s?'selected':''),`data-value="${s}" aria-pressed="${state.energy===s}"`)).join('')}</div></fieldset><label class="field">Subject or topic <span class="optional">optional</span><input id="topic" data-field="topic" maxlength="100" value="${h(state.topic)}" placeholder="e.g. Algebra · factoring"></label><div class="flow-actions">${btn('Back','back-details','btn secondary')}${btn('Make my plan '+icon('arrow'),'make-plan','btn primary')}</div></div></div></section>`;}
function planView(){if(!state.plan)return `<section class="wrap empty-page"><div class="big-icon">${icon('compass')}</div><h1>Your next step<br>starts <em>here.</em></h1><p>Choose what’s in the way. We’ll help you find a manageable place to begin.</p>${btn('Find my next step '+icon('arrow'),'home','btn primary')}</section>`;const p=buildPlan(state);const sources=p.sourceIds.map(id=>evidenceSources.find(s=>s.id===id)).filter(Boolean);return `<section class="wrap plan-page"><div class="section-heading"><div><span class="eyebrow">YOUR PLAN / ONE THING AT A TIME</span><h1>${h(p.card.title)}</h1><p>Starting with: <strong>${h(p.detail)}</strong>${state.topic?' · '+h(state.topic):''}</p></div>${btn(icon('download')+'Keep a copy','download-plan','btn secondary')}</div>${state.details.length>1?`<div class="plan-focus"><span>Change your focus:</span>${state.details.map(d=>btn(h(d),'primary-detail','chip '+(p.detail===d?'selected':''),`data-value="${h(d)}" aria-pressed="${p.detail===d}"`)).join('')}</div>`:''}${state.explanation?`<div class="your-note"><strong>Your words</strong><p>${h(state.explanation)}</p><small>This note is not interpreted by the app.</small></div>`:''}
 <div class="plan-layout"><div><article class="first-step"><div class="first-step-top"><span class="eyebrow">01 / TRY THIS FIRST</span><span class="time-badge">${p.kind==='study'?icon('clock')+p.duration+' min':'Support at your pace'}</span></div><h2>${h(p.first)}</h2><p>${p.kind==='study'?'Your goal is a first attempt. You can stop after this step.':'Choose what is safe and manageable for you. You do not have to do schoolwork first.'}</p><div class="first-buttons">${btn(state.done.includes(0)?'Start again':(p.kind==='study'?'Start this step '+icon('arrow'):icon('mail')+'Help me ask'),'start-step','btn primary')}${btn('Make it smaller','smaller','btn soft')}</div>${btn(state.done.includes(0)?icon('check')+'Marked complete':'I took this step','mark-first','text-link complete-first')}${state.timer>0||state.running?`<div class="focus-timer"><span class="timer-readout" role="timer" aria-label="Time remaining">${timerText()}</span>${btn(state.running?'Pause':'Resume','timer','chip')}${btn('Finish session','finish-timer','text-link')}</div>`:''}</article>
 <article class="panel plan-steps"><div class="section-heading"><h2>If you want to continue</h2><small>${state.done.filter(n=>n>0).length} of ${p.steps.length} steps</small></div>${p.steps.map((s,n)=>`<label class="check-step ${state.done.includes(n+1)?'done':''}"><input type="checkbox" data-step="${n+1}" ${state.done.includes(n+1)?'checked':''}><span>${n+2}</span><p>${h(s)}</p></label>`).join('')}${p.card.note?`<p class="content-note">${h(p.card.note)}</p>`:''}</article><div class="plan-tools">${btn('This doesn’t fit','fit','chip')}${btn('Try asking someone','ask-approach','chip')}${btn('Edit my choices','edit','chip')}</div></div>
 <aside class="plan-sidebar"><article class="panel help-card"><span class="category-icon tone-1">${icon('people')}</span><h2>A person can help.</h2><p>${h(p.support)}</p>${btn('Help me find the words '+icon('arrow'),'draft','btn secondary full')}${btn('Explore support options','support','text-link')}</article><article class="panel evidence-card"><span class="eyebrow">WHY THIS APPROACH?</span>${sources.length?sources.map(s=>`<button class="source-mini" data-action="source" data-value="${h(s.id)}"><span>${h(s.type)}</span><strong>${h(s.org)}</strong>${icon('arrow')}</button>`).join(''):'<p>App-designed support navigation. Qualified review is pending.</p>'}<p class="fineprint">Sources support specific ideas. This combined plan and its timing have not been evaluated.</p>${btn('Explore the research','open-research','text-link')}</article></aside></div><article class="checkin panel"><div><span class="eyebrow">A QUICK CHECK-IN</span><h2>Did you find a way to start?</h2></div><div class="chips">${['Yes, I started','Still stuck','I need a person'].map(s=>btn(s,'feedback','chip '+(state.feedback===s?'selected':''),`data-value="${s}"`)).join('')}</div>${state.feedback==='Yes, I started'?'<p class="feedback-note">That first step counts. Continue, take a break, or leave yourself a way back.</p>':''}</article></section>`;}
function timerText(){return `${Math.floor(state.timer/60)}:${String(state.timer%60).padStart(2,'0')}`;}
const methods=[['Recall','layers','Remember & review'],['Examples','book','See it, then try it'],['Mistakes','target','Learn from one error'],['Planner','clock','Make room for it'],['Grades','compass','Check the numbers']];
function studyView(){return `<section class="wrap studio"><div class="studio-heading"><div><span class="eyebrow">YOUR STUDY STUDIO</span><h1>Less guessing.<br><em>More learning.</em></h1><p>Small tools that make the next session useful.</p></div><div class="save-control">${btn(icon(state.saveWork?'check':'shield')+(state.saveWork?'Saving study work on this device':'Save study work on this device'),'save-work','btn secondary',`aria-pressed="${state.saveWork}"`)}<small>${state.saveWork?'Study work is saved in this browser.':'Your work stays in this tab until you refresh.'}</small></div></div><div class="studio-layout"><nav class="studio-nav" aria-label="Study tools">${methods.map(([s,ic,desc])=>btn(icon(ic)+`<span><strong>${s}</strong><small>${desc}</small></span>`,'method','tool-tab '+(state.method===s?'active':''),`data-value="${s}" aria-current="${state.method===s?'page':'false'}"`)).join('')}</nav><div class="studio-content">${state.method==='Recall'?recallView():state.method==='Examples'?exampleView():state.method==='Mistakes'?mistakesView():state.method==='Planner'?taskView():gradeView()}</div></div></section>`;}
function recallView(){const w=state.study;return `<div class="tool-heading"><span class="tool-label">RETRIEVAL PRACTICE</span><h2>See what sticks.</h2><p>Close your notes. Try an answer. Then check and correct it.</p></div><article class="panel"><label class="field">A question worth remembering<input id="recall-question" data-work="question" value="${h(w.question)}" placeholder="e.g. How does an enzyme affect activation energy?"></label><label class="field">Your answer, from memory<textarea id="recall-answer" data-work="answer" placeholder="Try before checking. An incomplete answer is useful information.">${h(w.answer)}</textarea></label>${btn(w.reveal?'Hide checking area':'I’ve tried—check my answer '+icon('arrow'),'reveal','btn secondary')}${w.reveal?`<div class="reveal-area"><p>Open your notes or a trusted explanation. Compare it with your attempt; this tool does not automatically grade your answer.</p><label class="field">Correct answer or missing detail<textarea id="correction" data-work="correction" placeholder="Write a checked answer for your review card.">${h(w.correction)}</textarea></label>${btn('Add to my review cards '+icon('plus'),'add-card','btn primary')}</div>`:''}</article><div class="section-heading deck-heading"><div><h2>Your review cards <span class="count">${w.cards.length}</span></h2><p>Review dates are adjustable app defaults, not a proven optimal schedule.</p></div></div>${w.cards.length?`<div class="review-grid">${w.cards.map(c=>`<article class="review-card"><div class="review-meta"><span>${c.next<=today()?'Ready to review':'Next: '+h(c.next)}</span>${btn(icon('close'),'remove-card','icon-btn',`data-id="${h(c.id)}" aria-label="Remove review card"`)}</div><h3>${h(c.question)}</h3>${w.flipped.includes(c.id)?`<p class="checked-answer">${h(c.answer)}</p><span class="fineprint">How did recall go?</span><div class="chips">${[['again','Again'],['hard','Hard'],['got','Got it']].map(([v,l])=>btn(l,'rate-card','chip',`data-id="${h(c.id)}" data-value="${v}"`)).join('')}</div>`:btn('Show checked answer','flip-card','text-link',`data-id="${h(c.id)}"`)}<label class="review-date">Review on<input aria-label="Review date for ${h(c.question)}" type="date" value="${h(c.next)}" data-review-date="${h(c.id)}"></label></article>`).join('')}</div>`:'<div class="empty-inline">'+icon('layers')+'Your first checked answer can become your first review card.</div>'}${btn('Why recall and spacing? '+icon('external'),'recall-sources','text-link source-foot')}`;}
function exampleView(){const w=state.study,e=examples.find(x=>x.id===w.example)||examples[0];return `<div class="tool-heading"><span class="tool-label">WORKED EXAMPLES</span><h2>Watch the steps. Then take one.</h2><p>Understand an example, then solve a related problem yourself.</p></div><label class="field example-select">Choose a topic<select id="example-select" data-work="example">${examples.map(x=>`<option value="${x.id}" ${x.id===e.id?'selected':''}>${h(x.subject+' · '+x.topic)}</option>`).join('')}</select></label><article class="panel worked-example"><span class="tag lavender">${h(e.subject)}</span><h2>${h(e.title)}</h2><p class="question-display">${h(e.question)}</p><ol class="worked-steps">${e.steps.map(s=>`<li>${h(s)}</li>`).join('')}</ol><div class="practice-box"><span class="eyebrow">NOW IT’S YOUR TURN</span><label class="field">${h(e.practice)}<input id="example-answer" data-work="exampleAnswer" type="number" step="any" value="${h(w.exampleAnswer)}" placeholder="Your answer"></label><div class="chips">${btn('Check my answer','check-example','btn primary')}${btn(w.hint?'Hide hint':'A small hint','hint','btn secondary')}</div>${w.hint?`<p class="hint">${h(e.hint)}</p>`:''}<p class="answer-feedback" role="status">${h(w.exampleFeedback)}</p></div><p class="fineprint">Examples are app-authored and arithmetic-checked; they have not had independent educator review. Check against your course materials.</p></article>`;}
function mistakesView(){const w=state.study;return `<div class="tool-heading"><span class="tool-label">ERROR REVIEW</span><h2>One mistake. Something to learn.</h2><p>Find the cause, check the reasoning, and try a related question.</p></div><article class="panel"><label class="field">What was the question?<textarea id="error-question" data-work="errorQuestion" placeholder="Paste or summarize one question.">${h(w.errorQuestion)}</textarea></label><label class="field">What got in the way?<select id="error-type" data-work="errorType">${['Understanding','Remembering','Applying','Reading the question','Time','Nerves','Not sure—ask a teacher'].map(s=>`<option ${w.errorType===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="field">Correct reasoning and one thing to try next<textarea id="error-reason" data-work="errorReason" placeholder="Check the explanation with notes, a worked solution, or a teacher.">${h(w.errorReason)}</textarea></label>${btn('Keep this lesson '+icon('plus'),'add-error','btn primary')}</article>${w.errors.length?`<div class="error-list">${w.errors.map(e=>`<article class="panel error-entry"><span class="tag">${h(e.type)}</span><h3>${h(e.question)}</h3><p>${h(e.reason)}</p>${btn('Turn into a recall question '+icon('arrow'),'error-to-card','text-link',`data-id="${h(e.id)}"`)}</article>`).join('')}</div>`:''}`;}
function taskView(){const w=state.study;return `<div class="tool-heading"><span class="tool-label">DEADLINE PLANNER</span><h2>Get it out of your head.</h2><p>Give each task a small finish point. Tasks sort by deadline.</p></div><article class="panel"><div class="task-fields"><label class="field">One task or finish point<input id="task-title" data-work="taskTitle" value="${h(w.taskTitle)}" placeholder="e.g. Try three projectile questions"></label><label class="field">Due date<input id="task-date" data-work="taskDate" type="date" value="${h(w.taskDate)}"></label><label class="field">Minutes<input id="task-minutes" data-work="taskMinutes" type="number" min="1" max="180" value="${h(w.taskMinutes)}"></label></div>${btn('Add my task '+icon('plus'),'add-task','btn primary')}</article>${w.tasks.length?`<div class="task-list">${[...w.tasks].sort((a,b)=>Number(a.done)-Number(b.done)||(a.date||'9999').localeCompare(b.date||'9999')).map(t=>`<article class="task-row ${t.done?'done':''}"><input aria-label="Complete ${h(t.title)}" type="checkbox" data-task="${h(t.id)}" ${t.done?'checked':''}><div><h3>${h(t.title)}</h3><span>${t.date?'Due '+h(t.date):'No date set'} · ${h(t.minutes)} min</span></div>${btn(icon('close'),'remove-task','icon-btn',`data-id="${h(t.id)}" aria-label="Remove ${h(t.title)}"`)}</article>`).join('')}</div>`:'<div class="empty-inline">'+icon('clock')+'A clear finish point is a good place to start.</div>'}<aside class="studio-tip">${icon('moon')}<p>Leave space for meals, rest, and getting help. Available time is a limit, not a target to fill.</p></aside>`;}
function gradeView(){const w=state.study;const result=calculateGrade(w.grades);return `<div class="tool-heading"><span class="tool-label">WEIGHTED GRADE CHECK</span><h2>Know where you stand.</h2><p>Enter your category averages and your teacher’s actual weights.</p></div><article class="panel"><div class="grade-table"><div class="grade-labels"><span>Category</span><span>Average / 100</span><span>Weight %</span></div>${w.grades.map((r,n)=>`<div class="grade-row"><input aria-label="Category ${n+1} name" data-grade="${n}:name" value="${h(r.name)}"><input type="number" min="0" max="100" step="any" aria-label="Category ${n+1} average" data-grade="${n}:score" value="${h(r.score)}"><input type="number" min="0" max="100" step="any" aria-label="Category ${n+1} weight" data-grade="${n}:weight" value="${h(r.weight)}"></div>`).join('')}</div>${btn('Calculate my average','calculate-grade','btn primary')}<div class="grade-result" id="grade-result" aria-live="polite">${result===null?'Weights must total 100%, and averages must be between 0 and 100.':`<strong>${result.toFixed(1)}%</strong><span>Weighted category average</span>`}</div><p class="fineprint">The filled values are editable examples, not your grades. This estimates category weighting only; retest rules, rounding, missing grades, and semester exams can change the official result.</p></article>`;}
function researchView(){return `<section class="wrap research-page"><div class="research-heading"><div><span class="eyebrow">FOLLOW THE EVIDENCE</span><h1>Curiosity, <em>with receipts.</em></h1><p>Explore the ideas behind better learning and student support.</p></div><div class="research-count"><strong>${Number(researchSummary.count).toLocaleString()}</strong><span>papers indexed<br>Not individually appraised</span></div></div><div class="research-switch">${btn('Research index','research-tab','chip '+(state.researchTab==='papers'?'selected':''),'data-value="papers"')}${btn(`${evidenceSources.length} checked source summaries`,'research-tab','chip '+(state.researchTab==='sources'?'selected':''),'data-value="sources"')}${btn('How this library works','methods','text-link')}</div><div class="research-explainer">${icon('book')}<p>${state.researchTab==='papers'?'Article records collected from Europe PMC / PubMed. Search matches and publication labels do not establish study quality, causation, or that this app works.':'These summaries were checked against linked sources. They support selected ideas; app-authored plans and sensitive support routes have not had independent professional review.'}</p></div>${state.researchTab==='papers'?researchPapers():`<div class="source-grid">${evidenceSources.map(sourceCard).join('')}</div>`}</section>`;}
function researchPapers(){if(!catalog)return `<article class="panel research-loading"><h2>${catalogError?'The index needs a connection.':'Opening the research index…'}</h2><p>${h(catalogError||'Loading article titles, links, publication types, and topic tags.')}</p>${catalogError?btn('Try again','retry-catalog','btn secondary'):''}</article>`;const topics=[...new Set(catalog.papers.flatMap(p=>p.topics))].sort();const types=[...new Set(catalog.papers.map(p=>p.type))].sort();let list=catalog.papers.filter(p=>(state.researchTopic==='All topics'||p.topics.includes(state.researchTopic))&&(state.researchType==='All types'||p.type===state.researchType)&&(state.researchYear==='Any year'||p.year>=Number(state.researchYear))&&`${p.title} ${p.authors} ${p.journal} ${p.doi||''} ${p.topics.join(' ')}`.toLowerCase().includes(state.researchQuery.toLowerCase()));if(state.researchSort==='Newest')list.sort((a,b)=>b.year-a.year);if(state.researchSort==='Most cited')list.sort((a,b)=>(b.citedBy||0)-(a.citedBy||0));const pages=Math.max(1,Math.ceil(list.length/18));state.researchPage=Math.min(state.researchPage,pages);const page=list.slice((state.researchPage-1)*18,state.researchPage*18);return `<div class="research-filters"><label class="search-field">${icon('search')}<input id="research-search" data-field="researchQuery" value="${h(state.researchQuery)}" placeholder="Search titles, authors, journal, DOI…" aria-label="Search research papers"></label><div class="filter-row">${[['researchTopic','Topic',['All topics',...topics]],['researchType','Publication type',['All types',...types]],['researchYear','Published',['Any year','2020','2015','2010']],['researchSort','Sort',['Catalog order','Newest','Most cited']]].map(([field,label,options])=>`<label>${label}<select id="${field}" data-field="${field}">${options.map(o=>`<option value="${h(o)}" ${state[field]===o?'selected':''}>${h(field==='researchYear'&&o!=='Any year'?'Since '+o:o)}</option>`).join('')}</select></label>`).join('')}</div></div><div class="research-results-header"><span role="status" aria-live="polite"><strong>${list.length.toLocaleString()}</strong> matching papers · Page ${state.researchPage} of ${pages}</span>${btn(icon('download')+'Export this view','export-research','text-link')}${btn('Clear filters','clear-research','text-link')}</div>${page.length?`<div class="paper-grid">${page.map(p=>`<article class="paper-card"><div class="paper-meta"><span class="tag ${/review|meta/i.test(p.type)?'lavender':''}">${h(p.type)}</span><span>${h(p.year)}</span></div><h2><a href="${h(p.url)}" target="_blank" rel="noopener noreferrer">${h(p.title)}${icon('external')}</a></h2><p class="paper-authors">${h(p.authors)}</p><p class="paper-journal">${h(p.journal)}</p><div class="paper-topics">${p.topics.map(t=>`<span>${h(t)}</span>`).join('')}</div><div class="paper-foot"><span>Indexed · ${h(p.source)}</span>${p.doi?`<span class="doi">DOI: ${h(p.doi)}</span>`:''}</div></article>`).join('')}</div>`:'<div class="empty-state">No papers match these filters. Try a broader term or clear the filters.</div>'}<div class="pagination">${btn('← Previous','previous-papers','btn secondary',state.researchPage<=1?'disabled':'')}<span>${state.researchPage} / ${pages}</span>${btn('Next '+icon('arrow'),'next-papers','btn secondary',state.researchPage>=pages?'disabled':'')}</div>`;}
function sourceCard(s){return `<article class="source-card"><span class="tag lavender">${h(s.type)}</span><h2>${link(h(s.title),s.url)}</h2><p class="source-org">${h(s.org)}${s.year?' · '+h(s.year):''}</p><p>${h(s.claim)}</p><div class="source-limit"><strong>What this does not establish</strong><p>${h(s.limit)}</p></div><small>Source checked ${h(s.checked)} · App adaptation untested</small></article>`;}
function openModal(name,ids=[]){lastFocus=document.activeElement?.getAttribute('data-action');state.modal=name;state.sourceIds=ids;render();$('.modal')?.focus();}
function draftText(){const p=state.plan?buildPlan(state):null;const topic=state.topic?` with ${state.topic}`:'';const messages={'Private conversation':'Hi, I’m finding things difficult right now. Could we find a private time to talk about support and one manageable next step? I’d prefer to share more when we speak.','Learning help':`Hi, I’m having trouble${topic||' with part of the course'}. Could we go through one example and work out what I should practise next?`,'More time':'Hi, I’m having difficulty keeping up with the current deadline. Could we discuss a realistic extension or which task I should prioritise first? I can share more privately.','Access or accommodations':'Hi, I’m having difficulty accessing or completing some course work. Could we discuss accessible materials, existing support, or how to request an accommodations meeting?','Practical support':'Hi, I need help accessing a practical resource such as food, transport, a device, or a quiet place to work. Could you help me find the right school or community service?'};return messages[state.draftKind]||messages['Private conversation'];}
function modalView(){let body='';if(state.modal==='privacy')body=`<span class="eyebrow">YOUR CHOICES</span><h2>Your work. Your control.</h2><p>No account, analytics, ads, or message sending. Your selections, plan, and unfinished fields stay in this tab’s memory until you refresh or close it.</p><p><strong>Optional device saving</strong> keeps only Study studio work—review cards, mistakes, tasks, and grade inputs—in this browser’s local storage. It does not save your selected personal situations or support drafts. Avoid sensitive details on a shared device.</p><p>External research and support sites have their own policies. Copying puts text on your clipboard; downloaded plans remain on your device.</p><div class="modal-actions">${btn('Clear saved study work','clear-saved','btn secondary')}${btn('Reset this session','reset-session','btn secondary')}</div><p class="fineprint">Resetting does not erase browser history, downloads, or copied text.</p>`;
else if(state.modal==='methods')body=`<span class="eyebrow">HOW WE USE RESEARCH</span><h2>Evidence you can inspect.</h2><div class="method-level"><span class="tag">1 · Indexed</span><p><strong>${Number(researchSummary.count).toLocaleString()} real article records</strong> collected from Europe PMC / PubMed across student-support topics. Deduplicated by DOI / PubMed ID. The records were not all read or critically appraised. Topic matching is automated and may be imperfect.</p></div><div class="method-level"><span class="tag lavender">2 · Source checked</span><p><strong>${evidenceSources.length} source summaries</strong> linked to practical ideas. Research reviews, original studies, and institutional guidance have different purposes. A source check is not an independent professional review.</p></div><div class="method-level"><span class="tag peach">3 · App-designed</span><p>Response cards, example problems, session timings, and review schedules are app adaptations. They have not been evaluated as a combined intervention and do not establish grade or health benefits.</p></div><p>Sensitive support content is general navigation and awaits qualified review. This tool does not diagnose, provide treatment, or monitor anyone’s safety.</p><p class="fineprint">Index cutoff: November 4, 2026. Methods and reproducible collection script are included in the source repository.</p>`;
else if(state.modal==='source'){const sources=state.sourceIds.map(id=>evidenceSources.find(s=>s.id===id)).filter(Boolean);body=`<span class="eyebrow">SOURCE & SCOPE</span><h2>Why this idea?</h2>${sources.length?sources.map(sourceCard).join(''):'<p>This is app-designed support navigation. Qualified review is pending.</p>'}`;}
else if(state.modal==='fit')body=`<span class="eyebrow">LET’S ADJUST IT</span><h2>What needs to change?</h2><p>You get to choose what fits.</p><div class="fit-options">${btn('<strong>It’s too much.</strong><span>Give me the smallest useful version.</span>','fit-smaller','fit-option')}${btn('<strong>It’s the wrong problem.</strong><span>Change the situation we start with.</span>','fit-edit','fit-option')}${btn('<strong>I need an explanation.</strong><span>Try a worked example in the studio.</span>','fit-example','fit-option')}${btn('<strong>I need someone’s help.</strong><span>Find a person and a way to ask.</span>','fit-support','fit-option')}</div>`;
else if(state.modal==='draft')body=`<span class="eyebrow">FIND THE WORDS</span><h2>You choose what to share.</h2><p>Edit this draft. Nothing is sent by the app.</p><label class="field">What are you asking for?<select id="draft-kind" data-field="draftKind">${['Private conversation','Learning help','More time','Access or accommodations','Practical support'].map(s=>`<option ${state.draftKind===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="field">Your draft<textarea id="support-draft" data-field="draft" rows="7">${h(state.draft||draftText())}</textarea></label>${btn(icon('mail')+'Copy my draft','copy-draft','btn primary')}<p class="fineprint">Copying does not send a message or contact anyone.</p>`;
else body=`<span class="eyebrow">HUMAN SUPPORT</span><h2>You don’t have to handle it alone.</h2><p>If you are in immediate danger or have an urgent medical need, contact your local emergency service or a safe nearby person or place if you can.</p><div class="support-notice">${icon('heart')}<p>This app is not monitored and cannot contact anyone for you. You can ask for support without completing a study plan.</p></div><div class="support-options"><article><span class="category-icon tone-0">${icon('people')}</span><div><h3>School or college</h3><p>A counselor, teacher, nurse, academic advisor, accessibility team, or basic-needs office. Choose a safe person; it does not have to be a parent.</p></div></article><article><span class="category-icon tone-2">${icon('home')}</span><div><h3>Home or community</h3><p>A trusted adult, healthcare professional, youth service, or local community resource. Ask about availability, cost, eligibility, and confidentiality.</p></div></article></div>${link('Look up support by country','https://findahelpline.com/','btn secondary')}${btn('Help me draft a request '+icon('arrow'),'draft','btn primary')}<p class="fineprint">The directory is an external service. Local availability and eligibility vary. Support pathways await qualified safeguarding review.</p>`;
return `<div class="modal-backdrop" data-backdrop><section class="modal" role="dialog" aria-modal="true" aria-label="${h({privacy:'Privacy and your choices',methods:'Research methods',source:'Sources and scope',fit:'Adjust your plan',draft:'Draft a support request',support:'Human support'}[state.modal]||'Support')}" tabindex="-1">${btn(icon('close'),'close','modal-close icon-btn','aria-label="Close dialog"')}${body}</section></div>`;}
function download(name,text,type='text/plain'){const a=document.createElement('a');const url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function updateInputView(id,start,end){render();const el=document.getElementById(id);el?.focus();if(el&&typeof el.setSelectionRange==='function'&&start!==null)try{el.setSelectionRange(start,end);}catch{}}
function resetPlan(){state.small=false;state.approach='';state.done=[];state.feedback='';state.timer=0;state.running=false;}
app.addEventListener('click',async event=>{
 const el=event.target.closest('[data-action]');if(!el)return;if(el.tagName==='A')event.preventDefault();const a=el.dataset.action,v=el.dataset.value,id=el.dataset.id;
 if(['support','privacy','methods','draft','fit'].includes(a)){if(a==='draft')state.draft='';openModal(a);return;}
 if(a==='source'){openModal('source',[v]);return;}
 if(a==='recall-sources'){openModal('source',evidenceSources.filter(s=>/retriev|learning techniques|organizing instruction/i.test(s.title+' '+s.claim)).map(s=>s.id));return;}
 if(a==='close'){state.modal=null;render();[...document.querySelectorAll('[data-action]')].find(x=>x.dataset.action===lastFocus)?.focus();return;}
 if(a==='nav'){navigate(el.dataset.page);return;}
 if(a==='home'||a==='back-home'){navigate('home');return;}
 if(a==='open-study'){navigate('study');return;}
 if(a==='open-research'){navigate('research');return;}
 if(a==='jump-categories'){if(state.page!=='home')navigate('home');$('#choose').scrollIntoView({behavior:'smooth',block:'start'});$('#category-search').focus({preventScroll:true});return;}
 if(a==='quick-study'){state.selected=['start'];state.details=['Can’t start'];state.primary='Can’t start';state.priority='Start schoolwork';state.safe='';resetPlan();navigate('context');return;}
 if(a==='show-all')state.showAll=!state.showAll;
 if(a==='category'||a==='other'){state.selected=state.selected.includes(v)?state.selected.filter(x=>x!==v):[...state.selected,v];state.details=state.details.filter(d=>categories.some(c=>state.selected.includes(c.id)&&c.subs.includes(d)));state.safe='';}
 if(a==='continue'){navigate('details');return;}
 if(a==='detail'){state.details=state.details.includes(v)?state.details.filter(d=>d!==v):[...state.details,v];state.safe='';}
 if(a==='to-context'){state.primary=state.details[0]||'';navigate('context');return;}
 if(a==='back-details'){navigate('details');return;}
 if(a==='minutes')state.minutes=Number(v);
 if(a==='energy')state.energy=v;
 if(a==='safe'){state.safe=v;if(v==='No'||v==='Not sure'){state.priority='Find a person to help';openModal('support');return;}}
 if(a==='make-plan'){resetPlan();state.plan=true;if(['No','Not sure'].includes(state.safe))state.priority='Find a person to help';navigate('plan');return;}
 if(a==='primary-detail'){state.primary=v;resetPlan();}
 if(a==='smaller'||a==='fit-smaller'){state.small=true;state.modal=null;state.done=[];state.timer=0;state.running=false;}
 if(a==='ask-approach'){state.approach='ask';state.done=[];}
 if(a==='edit'||a==='fit-edit'){navigate('details');return;}
 if(a==='fit-example'){state.method='Examples';navigate('study');return;}
 if(a==='fit-support'){openModal('support');return;}
 if(a==='start-step'){const p=buildPlan(state);if(p.kind!=='study'){state.draft='';openModal('draft');return;}state.timer=p.duration*60;state.running=true;}
 if(a==='timer')state.running=!state.running;
 if(a==='finish-timer'){state.running=false;state.timer=0;}
 if(a==='mark-first'){state.done=state.done.includes(0)?state.done.filter(n=>n!==0):[...state.done,0];}
 if(a==='feedback'){state.feedback=v;if(v==='Still stuck'){openModal('fit');return;}if(v==='I need a person'){openModal('support');return;}}
 if(a==='method')state.method=v;
 if(a==='save-work'){state.saveWork=!state.saveWork;if(!state.saveWork)try{localStorage.removeItem(key);}catch{}else persist();}
 if(a==='reveal')state.study.reveal=!state.study.reveal;
 if(a==='add-card'){const w=state.study;if(!w.question.trim()||!w.correction.trim()){toast('Add a question and a checked answer first.');return;}w.cards.unshift({id:crypto.randomUUID(),question:w.question.trim(),answer:w.correction.trim(),next:reviewDate('again')});w.question='';w.answer='';w.correction='';w.reveal=false;persist();}
 if(a==='flip-card'){state.study.flipped.push(id);}
 if(a==='rate-card'){const c=state.study.cards.find(c=>c.id===id);if(c)c.next=reviewDate(v);state.study.flipped=state.study.flipped.filter(x=>x!==id);persist();}
 if(a==='remove-card'){state.study.cards=state.study.cards.filter(c=>c.id!==id);persist();}
 if(a==='hint')state.study.hint=!state.study.hint;
 if(a==='check-example'){const w=state.study,e=examples.find(e=>e.id===w.example)||examples[0];w.exampleFeedback=w.exampleAnswer===''?'Try a number first.':Math.abs(Number(w.exampleAnswer)-e.answer)<(e.tolerance||0.0001)?'That’s right. '+e.explanation:'Not yet. '+e.hint;}
 if(a==='add-error'){const w=state.study;if(!w.errorQuestion.trim()||!w.errorReason.trim()){toast('Add the question and checked reasoning first.');return;}w.errors.unshift({id:crypto.randomUUID(),question:w.errorQuestion,reason:w.errorReason,type:w.errorType});w.errorQuestion='';w.errorReason='';persist();}
 if(a==='error-to-card'){const e=state.study.errors.find(e=>e.id===id);if(e){state.study.question=e.question;state.study.correction=e.reason;state.study.reveal=true;state.method='Recall';}}
 if(a==='add-task'){const w=state.study;if(!w.taskTitle.trim()){toast('Give the task a small finish point.');return;}w.tasks.push({id:crypto.randomUUID(),title:w.taskTitle.trim(),date:w.taskDate,minutes:Math.max(1,Math.min(180,Number(w.taskMinutes)||20)),done:false});w.taskTitle='';persist();}
 if(a==='remove-task'){state.study.tasks=state.study.tasks.filter(t=>t.id!==id);persist();}
 if(a==='calculate-grade'){const result=calculateGrade(state.study.grades);$('#grade-result').innerHTML=result===null?'Weights must total 100%, and averages must be between 0 and 100.':`<strong>${result.toFixed(1)}%</strong><span>Weighted category average</span>`;persist();return;}
 if(a==='research-tab')state.researchTab=v;
 if(a==='next-papers'||a==='previous-papers'){state.researchPage+=a==='next-papers'?1:-1;render();$('.research-results-header').scrollIntoView({block:'start'});return;}
 if(a==='clear-research'){Object.assign(state,{researchQuery:'',researchTopic:'All topics',researchType:'All types',researchYear:'Any year',researchPage:1});}
 if(a==='retry-catalog'){catalogError='';loadCatalog();}
 if(a==='text')state.large=!state.large;
 if(a==='copy-draft'){const text=$('#support-draft').value;try{await navigator.clipboard.writeText(text);toast('Draft copied. You choose where and whether to share it.');}catch{toast('Select the draft and copy it manually; clipboard access is unavailable.');}return;}
 if(a==='download-plan'){const p=buildPlan(state);const sources=p.sourceIds.map(id=>evidenceSources.find(s=>s.id===id)).filter(Boolean);download('my-next-step.txt',`NEXT STEP\n${p.card.title}\n\nStarting with: ${p.detail}${state.topic?'\nTopic: '+state.topic:''}\n\nFIRST STEP\n${p.first}\n\nIF YOU WANT TO CONTINUE\n${p.steps.map((s,n)=>(n+1)+'. '+s).join('\n')}\n\nSMALLER VERSION\n${p.card.smaller}\n\nA PERSON TO ASK\n${p.support}\n\nSOURCES\n${sources.map(s=>s.title+'\n'+s.url+'\nScope: '+s.limit).join('\n\n')}\n\nApp-designed plan; not evaluated as an intervention. Not monitored.`);toast('Your plan was downloaded.');return;}
 if(a==='export-research'&&catalog){const papers=catalog.papers.filter(p=>(state.researchTopic==='All topics'||p.topics.includes(state.researchTopic))&&(state.researchType==='All types'||p.type===state.researchType)&&(state.researchYear==='Any year'||p.year>=Number(state.researchYear))&&`${p.title} ${p.authors} ${p.journal} ${p.doi||''} ${p.topics.join(' ')}`.toLowerCase().includes(state.researchQuery.toLowerCase()));const csv=v=>'"'+String(v??'').replace(/"/g,'""')+'"';download('next-step-research.csv',[['Title','Authors','Year','Journal','DOI','URL','Topics','Publication type','Status'].map(csv).join(','),...papers.map(p=>[p.title,p.authors,p.year,p.journal,p.doi,p.url,p.topics.join('; '),p.type,p.status].map(csv).join(','))].join('\r\n'),'text/csv');return;}
 if(a==='clear-saved'){try{localStorage.removeItem(key);}catch{}state.saveWork=false;render();$('.modal').focus();toast('Saved study work cleared. The current tab still contains your work.');return;}
 if(a==='reset-session'){try{localStorage.removeItem(key);}catch{}Object.assign(state,{page:'home',selected:[],details:[],primary:'',search:'',explanation:'',topic:'',minutes:15,energy:'Some',priority:'Make a plan',safe:'',plan:false,small:false,approach:'',done:[],feedback:'',draft:'',study:blankStudy(),saveWork:false,timer:0,running:false,modal:null});navigate('home');toast('This session and saved study work were cleared.');return;}
 const scroll=window.scrollY;render();[...document.querySelectorAll('[data-action]')].find(x=>x.dataset.action===a&&x.dataset.value===v&&x.dataset.id===id)?.focus({preventScroll:true});window.scrollTo({top:scroll,behavior:'instant'});
});
app.addEventListener('input',event=>{const el=event.target;if(el.dataset.field){let value=el.value;if(el.dataset.field==='minutes')value=Math.max(1,Math.min(60,Number(value)||1));state[el.dataset.field]=value;if(['search','researchQuery'].includes(el.dataset.field)){state.researchPage=1;updateInputView(el.id,el.selectionStart,el.selectionEnd);}}
 if(el.dataset.work){state.study[el.dataset.work]=el.value;persist();}
 if(el.dataset.grade){const [n,k]=el.dataset.grade.split(':');state.study.grades[Number(n)][k]=el.value;persist();}
});
app.addEventListener('change',event=>{const el=event.target;if(el.dataset.field){state[el.dataset.field]=el.value;if(el.tagName==='SELECT'){if(el.dataset.field==='draftKind')state.draft='';state.researchPage=1;render();document.getElementById(el.id)?.focus();}}
 if(el.dataset.work==='example'){state.study.example=el.value;state.study.exampleAnswer='';state.study.exampleFeedback='';state.study.hint=false;persist();render();$('#example-select').focus();}
 if(el.dataset.step){const n=Number(el.dataset.step);state.done=el.checked?[...new Set([...state.done,n])]:state.done.filter(x=>x!==n);render();[...document.querySelectorAll('[data-step]')].find(x=>x.dataset.step===String(n))?.focus({preventScroll:true});}
 if(el.dataset.task){const t=state.study.tasks.find(t=>t.id===el.dataset.task);if(t)t.done=el.checked;persist();render();[...document.querySelectorAll('[data-task]')].find(x=>x.dataset.task===el.dataset.task)?.focus({preventScroll:true});}
 if(el.dataset.reviewDate){const c=state.study.cards.find(c=>c.id===el.dataset.reviewDate);if(c)c.next=el.value;persist();}
});
document.addEventListener('keydown',event=>{if(!state.modal)return;if(event.key==='Escape'){state.modal=null;render();[...document.querySelectorAll('[data-action]')].find(x=>x.dataset.action===lastFocus)?.focus();}if(event.key==='Tab'){const items=[...$('.modal').querySelectorAll('button,a,input,select,textarea')].filter(x=>!x.disabled);const first=items[0],last=items.at(-1);if(event.shiftKey&&(document.activeElement===first||document.activeElement===$('.modal'))){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}});
setInterval(()=>{if(state.running&&state.timer>0){state.timer--;const el=$('.timer-readout');if(el)el.textContent=timerText();if(!state.timer){state.running=false;render();toast('Time to check in. Continue, take a break, or leave a note for next time.');}}},1000);
render();
